// =====================================================================
// I TRACCIATI DELLE STRADE DEL GUSTO — 154 percorsi
// =====================================================================
//
// Le strade del vino non esistono su OpenStreetMap come percorso (156
// relazioni in tutto il pianeta, 126 fra Germania e Austria): la linea di
// queste 154 e' calcolata col ROUTING FRA LE TAPPE del catalogo, sul
// grafo giusto — auto, bici o piedi. Segue strade vere, non taglia per i
// campi.
//
// 129 hanno un percorso stradale. Le altre sono in treno o in barca, o il
// routing non e' passato (isole, tappe irraggiungibili in auto): quelle
// hanno p='dritta' e la mappa le disegna grigie e tratteggiate, perche'
// una linea d'aria non e' una strada e non va spacciata per tale.
//
// Stanno nel codice e non solo sul DB per lo stesso motivo delle tappe:
// una strada del vino si percorre in campagna, dove il campo manca. 154 KB.
//
// Formato: polyline Google precisione 5, tratti separati da ';' —
// decodifica in src/lib/polyline.ts.
//
// GENERATO — non modificare a mano: rilancia
// scratch/genera-linee-gusto.mjs (che legge scratch/geometrie/gusto.ndjson,
// prodotto da scratch/geometrie-percorsi.mjs --gusto).
// =====================================================================

export interface TasteRouteLine {
  /** 'car' | 'bike' | 'foot' = percorso stradale; 'dritta' = linea d'aria. */
  p: string;
  km: number;
  /** Polyline codificata, uno o piu' tratti separati da ';'. */
  l: string;
}

